"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[29002],{81677(e,s,n){n.r(s),n.d(s,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>a,toc:()=>d});const a=JSON.parse('{"id":"cursos/docker/modulos/docker-cicd/cuestionario","title":"Cuestionario M21 \u2014 Docker en CI/CD","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/21-docker-cicd/cuestionario.md","sourceDirName":"cursos/docker/modulos/21-docker-cicd","slug":"/cursos/docker/modulos/docker-cicd/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/docker-cicd/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/docker-cicd/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/docker-cicd/ejercicio"}}');var i=n(74848),o=n(28453);const r={sidebar_label:"Cuestionario"},c="Cuestionario M21 \u2014 Docker en CI/CD",t={},d=[{value:"1. [Investigar] \xbfQu\xe9 es exactamente Dagger y c\xf3mo redefine el CI/CD basado en contenedores? \xbfEn qu\xe9 se diferencia de usar Docker directamente en GitHub Actions?",id:"1-investigar-qu\xe9-es-exactamente-dagger-y-c\xf3mo-redefine-el-cicd-basado-en-contenedores-en-qu\xe9-se-diferencia-de-usar-docker-directamente-en-github-actions",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente Tekton y c\xf3mo implementa pipelines nativos de Kubernetes? \xbfEn qu\xe9 se diferencia de Jenkins y GitHub Actions?",id:"2-investigar-qu\xe9-es-exactamente-tekton-y-c\xf3mo-implementa-pipelines-nativos-de-kubernetes-en-qu\xe9-se-diferencia-de-jenkins-y-github-actions",level:3},{value:"3. [Investigar] \xbfC\xf3mo funciona exactamente BuildKit con cache remoto (<code>type=registry</code>, <code>type=s3</code>, <code>type=gha</code>)? \xbfQu\xe9 estrategia de cache es \xf3ptima para monorepos con m\xfaltiples im\xe1genes?",id:"3-investigar-c\xf3mo-funciona-exactamente-buildkit-con-cache-remoto-typeregistry-types3-typegha-qu\xe9-estrategia-de-cache-es-\xf3ptima-para-monorepos-con-m\xfaltiples-im\xe1genes",level:3},{value:"4. [Investigar] \xbfQu\xe9 es exactamente el &quot;GitOps&quot; y c\xf3mo difiere del modelo CI-push tradicional para despliegue de contenedores? \xbfQu\xe9 herramientas implementan GitOps (ArgoCD, Flux)?",id:"4-investigar-qu\xe9-es-exactamente-el-gitops-y-c\xf3mo-difiere-del-modelo-ci-push-tradicional-para-despliegue-de-contenedores-qu\xe9-herramientas-implementan-gitops-argocd-flux",level:3},{value:"5. [Conectar] La clase menciona Kaniko. \xbfQu\xe9 otras herramientas existen para construir im\xe1genes sin Docker daemon (buildah, img, buildpacks)? \xbfCu\xe1ndo elegir cada una?",id:"5-conectar-la-clase-menciona-kaniko-qu\xe9-otras-herramientas-existen-para-construir-im\xe1genes-sin-docker-daemon-buildah-img-buildpacks-cu\xe1ndo-elegir-cada-una",level:3},{value:"6. [Conectar] \xbfC\xf3mo se relacionan los SBOMs y la firma de im\xe1genes con el pipeline CI/CD? \xbfD\xf3nde se generan y verifican en el flujo?",id:"6-conectar-c\xf3mo-se-relacionan-los-sboms-y-la-firma-de-im\xe1genes-con-el-pipeline-cicd-d\xf3nde-se-generan-y-verifican-en-el-flujo",level:3},{value:"7. [Conectar] La clase muestra <code>docker compose up -d</code> en CI. \xbfCu\xe1ndo es preferible <code>docker compose</code> vs Testcontainers vs Kubernetes para tests de integraci\xf3n en CI?",id:"7-conectar-la-clase-muestra-docker-compose-up--d-en-ci-cu\xe1ndo-es-preferible-docker-compose-vs-testcontainers-vs-kubernetes-para-tests-de-integraci\xf3n-en-ci",level:3},{value:"8. [Cuestionar] \xbfDeben los pipelines CI/CD ser &quot;container-first&quot; o &quot;pipeline-first&quot;? \xbfEs Docker el centro o es un step m\xe1s?",id:"8-cuestionar-deben-los-pipelines-cicd-ser-container-first-o-pipeline-first-es-docker-el-centro-o-es-un-step-m\xe1s",level:3},{value:"9. [Cuestionar] \xbfEs <code>latest</code> tag en CI/CD aceptable para staging pero no para producci\xf3n? \xbfO deber\xeda erradicarse completamente?",id:"9-cuestionar-es-latest-tag-en-cicd-aceptable-para-staging-pero-no-para-producci\xf3n-o-deber\xeda-erradicarse-completamente",level:3},{value:"10. [Cuestionar] \xbfDeben los equipos peque\xf1os adoptar GitOps o es demasiada complejidad para el beneficio?",id:"10-cuestionar-deben-los-equipos-peque\xf1os-adoptar-gitops-o-es-demasiada-complejidad-para-el-beneficio",level:3}];function l(e){const s={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(s.header,{children:(0,i.jsx)(s.h1,{id:"cuestionario-m21--docker-en-cicd",children:"Cuestionario M21 \u2014 Docker en CI/CD"})}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,i.jsx)(s.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"1-investigar-qu\xe9-es-exactamente-dagger-y-c\xf3mo-redefine-el-cicd-basado-en-contenedores-en-qu\xe9-se-diferencia-de-usar-docker-directamente-en-github-actions",children:"1. [Investigar] \xbfQu\xe9 es exactamente Dagger y c\xf3mo redefine el CI/CD basado en contenedores? \xbfEn qu\xe9 se diferencia de usar Docker directamente en GitHub Actions?"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": Dagger (dagger.io, Solomon Hykes, fundador de Docker) es un toolkit para construir pipelines CI/CD como c\xf3digo (en Go, TypeScript, Python) que se ejecutan completamente en contenedores. A diferencia de usar ",(0,i.jsx)(s.code,{children:"docker build"})," + ",(0,i.jsx)(s.code,{children:"docker push"})," en un script de GitHub Actions: 1) Dagger define pipelines como funciones en un lenguaje de programaci\xf3n real (no YAML), con tipos, testing, y reutilizaci\xf3n, 2) Los pipelines se ejecutan 100% en contenedores (el runner de CI solo necesita Dagger Engine, no herramientas espec\xedficas), 3) El cache de build es distribuido y compartido entre runners y desarrolladores locales (mismo pipeline corre en CI y en la laptop del dev), 4) Dagger usa BuildKit internamente para builds eficientes, pero abstrae la complejidad. Esencialmente, Dagger es a CI/CD lo que Docker fue a los contenedores: un est\xe1ndar para empaquetar y ejecutar pipelines."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),': Solomon Hykes present\xf3 Dagger en 2022 como "Docker for CI/CD". La visi\xf3n: pipelines como contenedores componibles, con cache universal, que corren igual en local y en CI. Docker en CI (GitHub Actions) es scripting imperativo + YAML. Dagger es c\xf3digo (type-safe, testable). Por ejemplo: ',(0,i.jsx)(s.code,{children:"dagger call build --source . publish --registry harbor.local"}),". La comunidad de Dagger est\xe1 creciendo (Dagger Zenith, m\xf3dulos reutilizables). Es un concepto nuevo; compite con Jenkins, GitHub Actions, y Tekton, no con Docker."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"2-investigar-qu\xe9-es-exactamente-tekton-y-c\xf3mo-implementa-pipelines-nativos-de-kubernetes-en-qu\xe9-se-diferencia-de-jenkins-y-github-actions",children:"2. [Investigar] \xbfQu\xe9 es exactamente Tekton y c\xf3mo implementa pipelines nativos de Kubernetes? \xbfEn qu\xe9 se diferencia de Jenkins y GitHub Actions?"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": Tekton (proyecto CDF/ Linux Foundation, basado en Knative Build) es un framework de CI/CD para Kubernetes que usa CRDs para definir pipelines, tasks, y triggers. Todo corre como Pods en K8s. Diferencia con Jenkins: 1) Tekton es serverless (cada step es un Pod que se ejecuta y termina, no hay un servidor Jenkins corriendo 24/7), 2) Los pipelines son recursos nativos de K8s (YAML, versionables en Git, aplicables con kubectl), 3) Escala horizontalmente con el cluster (no requiere infraestructura de CI separada). Diferencia con GitHub Actions: Tekton es cloud-agnostic (corre en cualquier K8s, no est\xe1 atado a GitHub), y los pipelines son recursos de K8s (no archivos en ",(0,i.jsx)(s.code,{children:".github/workflows"}),"). Desventaja: Tekton tiene una curva de aprendizaje m\xe1s alta (K8s + CRDs + Tasks)."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": Tekton fue creado por Google (basado en el sistema de build interno de Google) y donado a la CDF (Continuous Delivery Foundation). Es el est\xe1ndar de CI/CD nativo de K8s. Cada Task (unidad de trabajo: ",(0,i.jsx)(s.code,{children:"git-clone"}),", ",(0,i.jsx)(s.code,{children:"buildpacks"}),", ",(0,i.jsx)(s.code,{children:"kaniko"}),") es un contenedor. Las Tasks se encadenan en Pipelines. Tekton Triggers escuchan eventos (webhooks de GitHub) y disparan PipelineRuns. Para equipos que ya usan K8s, Tekton elimina la necesidad de un servidor de CI externo."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsxs)(s.h3,{id:"3-investigar-c\xf3mo-funciona-exactamente-buildkit-con-cache-remoto-typeregistry-types3-typegha-qu\xe9-estrategia-de-cache-es-\xf3ptima-para-monorepos-con-m\xfaltiples-im\xe1genes",children:["3. [Investigar] \xbfC\xf3mo funciona exactamente BuildKit con cache remoto (",(0,i.jsx)(s.code,{children:"type=registry"}),", ",(0,i.jsx)(s.code,{children:"type=s3"}),", ",(0,i.jsx)(s.code,{children:"type=gha"}),")? \xbfQu\xe9 estrategia de cache es \xf3ptima para monorepos con m\xfaltiples im\xe1genes?"]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": BuildKit soporta exportar e importar cache desde backends remotos: 1) ",(0,i.jsx)(s.code,{children:"type=registry"}),": sube las capas cacheadas como blobs OCI a un registry (Harbor, ECR). El pr\xf3ximo build importa las capas desde el registry en lugar de re-ejecutar comandos. Ventaja: funciona en cualquier entorno, no depende del CI. 2) ",(0,i.jsx)(s.code,{children:"type=gha"}),": usa el cache service de GitHub Actions (10 GB gratis). Ventaja: integraci\xf3n nativa con GitHub, cero configuraci\xf3n de registry. 3) ",(0,i.jsx)(s.code,{children:"type=s3"}),": usa S3 como storage de cache. Para monorepos con m\xfaltiples im\xe1genes: usar ",(0,i.jsx)(s.code,{children:"mode=max"})," (cachea todas las capas intermedias, no solo las de la imagen final) y scopes diferentes por imagen (",(0,i.jsx)(s.code,{children:"--cache-from type=registry,ref=myapp-cache:&#x3C;sha>,scope=service-a"}),"). El scope permite que caches de diferentes builds no se interfieran. ",(0,i.jsx)(s.code,{children:"mode=max"})," exporta capas de stages intermedios (build stage, dependency stage), no solo del stage final."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de BuildKit (github.com/moby/buildkit) detalla los backends de cache. ",(0,i.jsx)(s.code,{children:"mode=max"})," fue introducido en BuildKit 0.8 para multi-stage builds. Sin ",(0,i.jsx)(s.code,{children:"mode=max"}),", solo se cachea el stage final (imagen resultante). Con ",(0,i.jsx)(s.code,{children:"mode=max"}),", se cachean los stages intermedios (dependencies, build), permitiendo que builds de otros servicios reutilicen el cache de dependencias comunes. Para monorepos, ",(0,i.jsx)(s.code,{children:"scope"})," por servicio asegura que el cache de ",(0,i.jsx)(s.code,{children:"service-a"})," no polucione el de ",(0,i.jsx)(s.code,{children:"service-b"}),"."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"4-investigar-qu\xe9-es-exactamente-el-gitops-y-c\xf3mo-difiere-del-modelo-ci-push-tradicional-para-despliegue-de-contenedores-qu\xe9-herramientas-implementan-gitops-argocd-flux",children:'4. [Investigar] \xbfQu\xe9 es exactamente el "GitOps" y c\xf3mo difiere del modelo CI-push tradicional para despliegue de contenedores? \xbfQu\xe9 herramientas implementan GitOps (ArgoCD, Flux)?'}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": CI-push tradicional: el pipeline CI construye la imagen, ejecuta tests, y al final hace push al registry Y EJECUTA ",(0,i.jsx)(s.code,{children:"kubectl apply"})," o ",(0,i.jsx)(s.code,{children:"helm upgrade"}),' (el CI empuja cambios al cluster). Problemas: el CI necesita credenciales de deploy (riesgo de seguridad), si el cluster est\xe1 ca\xeddo el deploy falla (sin reintento autom\xe1tico), y no hay registro de qui\xe9n cambi\xf3 qu\xe9 (el CI act\xfaa como actor). GitOps: el pipeline CI construye la imagen y actualiza un repositorio Git (deployment config) con el nuevo tag/digest. Un agente en el cluster (ArgoCD, Flux) monitorea ese repo Git y reconcilia el cluster con el estado declarado en Git (pull). El cluster "jala" la configuraci\xf3n desde Git. Ventajas: 1) el CI no necesita credenciales del cluster, 2) el estado deseado est\xe1 versionado en Git, 3) el agente continuamente reconcilia (si alguien cambia algo manualmente en el cluster, el agente lo revierte), 4) rollback = revert commit en Git.']}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": GitOps fue acu\xf1ado por Weaveworks (Alexis Richardson) en 2017. ArgoCD (Intuit, CNCF graduado) y Flux (Weaveworks, CNCF graduado) son las implementaciones principales. La diferencia fundamental: CI-push = CI escribe en el cluster. GitOps = CI escribe en Git, el cluster lee de Git. Esto desacopla CI (build) de CD (deploy), mejora seguridad, y habilita multi-cluster (varios clusters leyendo del mismo Git)."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"5-conectar-la-clase-menciona-kaniko-qu\xe9-otras-herramientas-existen-para-construir-im\xe1genes-sin-docker-daemon-buildah-img-buildpacks-cu\xe1ndo-elegir-cada-una",children:"5. [Conectar] La clase menciona Kaniko. \xbfQu\xe9 otras herramientas existen para construir im\xe1genes sin Docker daemon (buildah, img, buildpacks)? \xbfCu\xe1ndo elegir cada una?"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": 1) ",(0,i.jsx)(s.strong,{children:"Kaniko"}),": interpreta Dockerfile en userspace, sin daemon, sin privilegios. Ideal para K8s (corre como Pod normal, sin Docker socket). 2) ",(0,i.jsx)(s.strong,{children:"Buildah"})," (Red Hat): construye im\xe1genes OCI desde l\xednea de comandos o Dockerfile. Puede correr rootless, sin daemon. Ideal para entornos RHEL/Fedora y scripts de build (no K8s nativo). 3) ",(0,i.jsx)(s.strong,{children:"img"})," (Jessie Frazelle): construye im\xe1genes sin daemon usando una biblioteca Go. Menos mantenido hoy. 4) ",(0,i.jsx)(s.strong,{children:"Cloud Native Buildpacks"})," (Heroku, VMware): construye im\xe1genes OCI sin Dockerfile, detectando el lenguaje y aplicando best practices autom\xe1ticamente. Ideal para aplicaciones est\xe1ndar (Spring Boot, Express, Django) sin escribir Dockerfile. 5) ",(0,i.jsx)(s.strong,{children:"BuildKit con rootless"}),": BuildKit puede correr sin root (rootless kit). Ideal para entornos donde necesit\xe1s compatibilidad Docker (Dockerfile) pero sin daemon root. Elecci\xf3n: Kaniko para CI en K8s (est\xe1ndar), Buildpacks si no quer\xe9s escribir Dockerfiles, Buildah si est\xe1s en RHEL, BuildKit rootless para casos avanzados."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": La deprecaci\xf3n de dockershim en K8s (1.24) cataliz\xf3 la adopci\xf3n de herramientas de build sin Docker daemon. Kaniko (Google, 2018) fue pionero. Buildah (2017) es parte del ecosistema Podman. Buildpacks (2018+) son promovidos por la CNCF y VMware Tanzu. La elecci\xf3n depende de si ten\xe9s Dockerfiles existentes (Kaniko/BuildKit) o quer\xe9s evitar Dockerfiles (Buildpacks)."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"6-conectar-c\xf3mo-se-relacionan-los-sboms-y-la-firma-de-im\xe1genes-con-el-pipeline-cicd-d\xf3nde-se-generan-y-verifican-en-el-flujo",children:"6. [Conectar] \xbfC\xf3mo se relacionan los SBOMs y la firma de im\xe1genes con el pipeline CI/CD? \xbfD\xf3nde se generan y verifican en el flujo?"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": En el pipeline CI/CD, la seguridad de supply chain sigue este flujo: 1) Build: se construye la imagen (BuildKit, Kaniko). 2) SBOM generation: inmediatamente despu\xe9s del build, se genera el SBOM de la imagen (Syft, Trivy) y se adjunta al registry (Cosign attach, ORAS). 3) Vulnerability scan: se escanea la imagen (Trivy, Docker Scout) usando el SBOM para identificar paquetes con CVEs. Si hay CRITICAL, el pipeline falla. 4) Sign: la imagen se firma (Cosign, Notation) con la identidad del pipeline. 5) Attestation: se firma una attestaci\xf3n que incluye el SBOM, los resultados del escaneo, y la procedencia (provenance). 6) Push: la imagen firmada + SBOM + attestaci\xf3n se suben al registry. 7) Verify (en deploy): antes de desplegar, el admission controller (Conaisseur, Kyverno) verifica la firma. Si la imagen no est\xe1 firmada o la firma no coincide, el deploy se rechaza."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": El supply chain security con SLSA (Supply-chain Levels for Software Artifacts, de Google) define niveles (L1-L4) de seguridad. Generar SBOM y firmar im\xe1genes alcanza SLSA L2-L3. Herramientas como Cosign, Syft, y SLSA GitHub Generator automatizan esto. La integraci\xf3n en CI/CD es crucial porque sin automatizaci\xf3n, los pasos de seguridad se omiten."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsxs)(s.h3,{id:"7-conectar-la-clase-muestra-docker-compose-up--d-en-ci-cu\xe1ndo-es-preferible-docker-compose-vs-testcontainers-vs-kubernetes-para-tests-de-integraci\xf3n-en-ci",children:["7. [Conectar] La clase muestra ",(0,i.jsx)(s.code,{children:"docker compose up -d"})," en CI. \xbfCu\xe1ndo es preferible ",(0,i.jsx)(s.code,{children:"docker compose"})," vs Testcontainers vs Kubernetes para tests de integraci\xf3n en CI?"]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": 1) ",(0,i.jsx)(s.code,{children:"docker compose"})," (o ",(0,i.jsx)(s.code,{children:"docker compose up --wait"}),"): bueno para tests que necesitan m\xfaltiples servicios reales (PostgreSQL + Redis + la app) en un entorno similar a producci\xf3n. El CI solo necesita Docker. 2) Testcontainers: bueno para tests unitarios/de integraci\xf3n desde el c\xf3digo (Java, Python, Go). Cada test levanta solo los servicios que necesita (contenedor PostgreSQL ef\xedmero). Ventaja: configuraci\xf3n en c\xf3digo, m\xe1s granular, auto-limpieza. 3) Kubernetes (kind, Minikube, o un namespace temporal en un cluster): bueno para tests que necesitan features de K8s (ConfigMaps, Secrets, Services, Ingress, NetworkPolicy). Es m\xe1s pesado (crear cluster/namespace) pero m\xe1s realista si producci\xf3n es K8s. Elecci\xf3n: Compose para CI simple, Testcontainers para tests desde c\xf3digo (sin YAML externo), K8s cuando prob\xe1s features espec\xedficas de K8s."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": La encuesta de Docker (2024) muestra que ",(0,i.jsx)(s.code,{children:"docker compose"})," sigue siendo la herramienta m\xe1s usada para CI. Testcontainers (proyecto CNCF, 2015) creci\xf3 en popularidad para tests de integraci\xf3n en lenguajes espec\xedficos. Kind es el est\xe1ndar para CI de aplicaciones K8s. La tendencia: usar Testcontainers para tests de integraci\xf3n en el c\xf3digo, y Compose/Kind para pruebas end-to-end en el pipeline."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"8-cuestionar-deben-los-pipelines-cicd-ser-container-first-o-pipeline-first-es-docker-el-centro-o-es-un-step-m\xe1s",children:'8. [Cuestionar] \xbfDeben los pipelines CI/CD ser "container-first" o "pipeline-first"? \xbfEs Docker el centro o es un step m\xe1s?'}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": Container-first (Docker como centro) significa que todos los steps del pipeline corren en contenedores: linting (Hadolint en contenedor), build (Kaniko/BuildKit), test (Testcontainers o ",(0,i.jsx)(s.code,{children:"docker compose"}),"), scan (Trivy en contenedor). Esto garantiza reproducibilidad: el pipeline corre igual en local y en CI. Pipeline-first (YAML del CI como centro) significa que algunos steps usan acciones nativas del CI (GitHub Actions, GitLab CI) sin Docker, y Docker es solo uno de los steps (el build de imagen). El debate: container-first es m\xe1s portable (cambi\xe1s de CI sin reescribir todo) pero puede ser m\xe1s lento (overhead de contenedores). Pipeline-first es m\xe1s integrado con el CI (mejor UX, logs, UI) pero vendor-lock. La tendencia: h\xedbrido \u2014 usar contenedores para steps que necesitan herramientas espec\xedficas, y actions nativas para integraci\xf3n con el CI."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),': Dagger (Solomon Hykes) aboga por container-first: "tu pipeline es una funci\xf3n que corre en un contenedor, en cualquier CI". GitHub Actions aboga por pipeline-first (actions del marketplace). La realidad pr\xe1ctica: para GitHub Actions, combinar ',(0,i.jsx)(s.code,{children:"docker/build-push-action"})," (container step) con ",(0,i.jsx)(s.code,{children:"actions/checkout"})," (native step) es el balance correcto. Para m\xe1xima portabilidad, Dagger o Tekton."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsxs)(s.h3,{id:"9-cuestionar-es-latest-tag-en-cicd-aceptable-para-staging-pero-no-para-producci\xf3n-o-deber\xeda-erradicarse-completamente",children:["9. [Cuestionar] \xbfEs ",(0,i.jsx)(s.code,{children:"latest"})," tag en CI/CD aceptable para staging pero no para producci\xf3n? \xbfO deber\xeda erradicarse completamente?"]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": ",(0,i.jsx)(s.code,{children:"latest"})," no deber\xeda usarse en ning\xfan entorno que requiera trazabilidad y reproducibilidad. Staging tambi\xe9n necesita saber exactamente qu\xe9 versi\xf3n se est\xe1 probando. Si staging usa ",(0,i.jsx)(s.code,{children:"latest"})," y producci\xf3n usa ",(0,i.jsx)(s.code,{children:"v1.2.3"}),", no hay garant\xeda de que lo mismo que pas\xf3 staging est\xe1 en producci\xf3n. El flujo correcto: 1) CI construye imagen con tag = git SHA (",(0,i.jsx)(s.code,{children:"a1b2c3d"}),"), 2) CI despliega en staging con ese SHA, 3) Despu\xe9s de tests, promociona a producci\xf3n con el mismo SHA (o tag sem\xe1ntico adicional ",(0,i.jsx)(s.code,{children:"v1.2.3"}),"). ",(0,i.jsx)(s.code,{children:"latest"})," solo es aceptable en desarrollo local (donde el dev siempre quiere lo \xfaltimo). Incluso en desarrollo, usar SHA da m\xe1s confianza: sab\xe9s exactamente qu\xe9 c\xf3digo est\xe1s ejecutando."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),': El anti-patr\xf3n "but it works on my machine" frecuentemente es "staging usa latest, que es diferente a lo que el dev ten\xeda localmente". La inmutabilidad de im\xe1genes es un principio fundamental de Docker. ',(0,i.jsx)(s.code,{children:"latest"})," rompe esto."]}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.h3,{id:"10-cuestionar-deben-los-equipos-peque\xf1os-adoptar-gitops-o-es-demasiada-complejidad-para-el-beneficio",children:"10. [Cuestionar] \xbfDeben los equipos peque\xf1os adoptar GitOps o es demasiada complejidad para el beneficio?"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Respuesta"}),": GitOps agrega complejidad (repositorio de config separado, ArgoCD/Flux en el cluster) pero tambi\xe9n agrega seguridad y auditabilidad. Para equipos peque\xf1os (2-5 personas) con 1-2 clusters y deploy simple, el overhead de GitOps puede no justificarse. En su lugar, ",(0,i.jsx)(s.code,{children:"kubectl apply"})," o ",(0,i.jsx)(s.code,{children:"helm upgrade --install"})," desde CI (CI-push) es suficiente y m\xe1s simple. GitOps brilla cuando: 1) m\xfaltiples clusters (staging, prod, multi-region), 2) m\xfaltiples equipos (control de qui\xe9n despliega qu\xe9), 3) requisitos de compliance (audit trail de cada cambio en Git), 4) necesidad de auto-remediation (si alguien cambia manualmente, GitOps lo revierte). La recomendaci\xf3n: empezar con CI-push simple, migrar a GitOps cuando la complejidad de gesti\xf3n de deploys supere la complejidad de configurar GitOps."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Por qu\xe9"}),": La curva de adopci\xf3n de GitOps documentada por Weaveworks y la CNCF muestra que GitOps se adopta t\xedpicamente en organizaciones con 5+ equipos de desarrollo. Para equipos peque\xf1os, la simplicidad de CI-push supera los beneficios de GitOps. Herramientas como ",(0,i.jsx)(s.code,{children:"kamal"})," (37signals) ofrecen un punto intermedio: deploy desde CI sin GitOps pero con zero-downtime."]})]})}function u(e={}){const{wrapper:s}={...(0,o.R)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,s,n){n.d(s,{R:()=>r,x:()=>c});var a=n(96540);const i={},o=a.createContext(i);function r(e){const s=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function c(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(o.Provider,{value:s},e.children)}}}]);